SELECT ID, CANAL_ID, YT_VIDEO_ID, TITULO, PUBLICADO_EM, DURACAO_SEG, TIPO, THUMB, STATUS, MOTIVO, ORIGEM, PROGRESSO_SEG, TENTATIVAS, RESUMO, INDISPONIVEL, ESTUDADO_EM, ATUALIZADO_EM, AVISO_ID, CRIADO_EM, PRIORIDADE, ORDEM, DESCOBERTA, TEMAS_EDITADOS, PRATICAS_EM FROM VIDEOS WHERE ID > {{depois}} ORDER BY ID LIMIT 2000